def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    history: list[tuple] = []
    rejected: list[int] = []

    def parse_amount(s: str):
        if not s or any(c not in "0123456789" for c in s):
            return None
        return int(s)

    def revert(rec: tuple) -> None:
        kind = rec[0]
        if kind == "open":
            _, a = rec
            del balances[a]
            frozen.discard(a)
        elif kind == "deposit":
            _, a, n = rec
            balances[a] -= n
        elif kind == "withdraw":
            _, a, n = rec
            balances[a] += n
        elif kind == "transfer":
            _, a, b, n = rec
            balances[a] += n
            balances[b] -= n
        elif kind == "freeze":
            _, a = rec
            frozen.discard(a)
        elif kind == "unfreeze":
            _, a = rec
            frozen.add(a)

    for i, op in enumerate(ops):
        t = op.split(" ")
        verb = t[0]
        rec = None
        ok = True

        if verb == "open" and len(t) == 3:
            a, n = t[1], parse_amount(t[2])
            if n is None or a in balances:
                ok = False
            else:
                balances[a] = n
                rec = ("open", a)

        elif verb == "deposit" and len(t) == 3:
            a, n = t[1], parse_amount(t[2])
            if n is None or n <= 0 or a not in balances:
                ok = False
            else:
                balances[a] += n
                rec = ("deposit", a, n)

        elif verb == "withdraw" and len(t) == 3:
            a, n = t[1], parse_amount(t[2])
            if (n is None or n <= 0 or a not in balances
                    or a in frozen or balances[a] < n):
                ok = False
            else:
                balances[a] -= n
                rec = ("withdraw", a, n)

        elif verb == "transfer" and len(t) == 4:
            a, b, n = t[1], t[2], parse_amount(t[3])
            if (n is None or n <= 0 or a == b
                    or a not in balances or b not in balances
                    or a in frozen or balances[a] < n):
                ok = False
            else:
                balances[a] -= n
                balances[b] += n
                rec = ("transfer", a, b, n)

        elif verb == "freeze" and len(t) == 2:
            a = t[1]
            if a not in balances or a in frozen:
                ok = False
            else:
                frozen.add(a)
                rec = ("freeze", a)

        elif verb == "unfreeze" and len(t) == 2:
            a = t[1]
            if a not in balances or a not in frozen:
                ok = False
            else:
                frozen.discard(a)
                rec = ("unfreeze", a)

        elif verb == "undo" and len(t) == 1:
            if not history:
                ok = False
            else:
                revert(history.pop())

        else:
            ok = False

        if not ok:
            rejected.append(i)
        elif rec is not None:
            history.append(rec)

    return dict(balances), rejected
